const lastname = pm.variables.replaceIn("{{$randomLastName}}");
const totalprice = Math.floor(Math.random() * 500) + 50;
const depositpaid = Math.random() < 0.5;


// Generate random checkin date within the next year
const today = new Date();
const checkinOffset = Math.floor(Math.random() * 365);
const checkinDate = new Date(today.getTime() + checkinOffset * 24 * 60 * 60 * 1000);
const checkin = checkinDate.toISOString().split("T")[0];

// Generate random checkout date 1–14 days after checkin
const checkoutOffset = Math.floor(Math.random() * 14) + 1;
const checkoutDate = new Date(checkinDate.getTime() + checkoutOffset * 24 * 60 * 60 * 1000);
const checkout = checkoutDate.toISOString().split("T")[0];

