pm.collectionVariables.set("booking_lastname", lastname);
pm.collectionVariables.set("booking_totalprice", totalprice);
pm.collectionVariables.set("booking_depositpaid", depositpaid);
pm.collectionVariables.set("booking_checkin", checkin);
pm.collectionVariables.set("booking_checkout", checkout);

// Parse the request body into a local JS object
const requestBody = JSON.parse(pm.request.body.raw);

// 1. Define the Expected JSON Schema
const bookingSchema = {
 "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "firstname": { "type": "string" },
    "lastname": { "type": "string" },
    "totalprice": { "type": "number" },
    "depositpaid": { "type": "boolean" },
    "bookingdates": {
      "type": "object",
      "properties": {
        "checkin": { 
          "type": "string",
          "pattern": "^\\d{4}-\\d{2}-\\d{2}$" // Matches CCYY-MM-DD
        },
        "checkout": { 
          "type": "string",
          "pattern": "^\\d{4}-\\d{2}-\\d{2}$" // Matches CCYY-MM-DD
        }
      },
      "required": ["checkin", "checkout"]
    },
    "additionalneeds": { "type": "string" }
  },
  "required": [
    "firstname",
    "lastname",
    "totalprice",
    "depositpaid",
    "bookingdates"
  ]
};

